/**
 * Reads an integer from the given input field. Returns 0 when the field is
 * missing, empty or does not hold a parsable number, so that an incomplete
 * input never crashes the dialog.
 */
private int readInt(int viewId){
    String value = readText(viewId);
    if(value.isEmpty())
        return 0;
    try {
        return Integer.parseInt(value);
    } catch (NumberFormatException e) {
        return 0;
    }
}

/**
 * Reads a double from the given input field. Returns 0.0 when the field is
 * missing, empty or does not hold a parsable number.
 */
private double readDouble(int viewId){
    String value = readText(viewId);
    if(value.isEmpty())
        return 0.0;
    try {
        return Double.parseDouble(value);
    } catch (NumberFormatException e) {
        return 0.0;
    }
}

private String readText(int viewId){
    TextView view = (TextView) dialog.findViewById(viewId);
    if(view == null || view.getText() == null)
        return "";
    return view.getText().toString().trim();
}

public void setSchedule(Schedule schedule){
    Schedule = schedule;
}
